import{_ as e,o,c as a,a6 as r}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"HTTP 缓存基石 · Cache-Control 全家桶","description":"浏览器和 CDN 到底怎么缓存，全由服务器的一个响应头说了算——Cache-Control。这一章把 max-age、s-maxage、public/private、no-cache/no-store、以及 ETag 条件请求讲透，它们是后面一切缓存策略的字母表。","frontmatter":{"title":"HTTP 缓存基石 · Cache-Control 全家桶","description":"浏览器和 CDN 到底怎么缓存，全由服务器的一个响应头说了算——Cache-Control。这一章把 max-age、s-maxage、public/private、no-cache/no-store、以及 ETag 条件请求讲透，它们是后面一切缓存策略的字母表。","source":"https://daiw.org/manual/ssr/http-caching"},"headers":[],"relativePath":"manual/computer-programming/ssr/http-caching.md","filePath":"manual/computer-programming/ssr/http-caching.md"}'),d={name:"manual/computer-programming/ssr/http-caching.md"};function c(s,t,n,l,i,p){return o(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="http-缓存基石-·-cache-control-全家桶" tabindex="-1">HTTP 缓存基石 · Cache-Control 全家桶 <a class="header-anchor" href="#http-缓存基石-·-cache-control-全家桶" aria-label="Permalink to &quot;HTTP 缓存基石 · Cache-Control 全家桶&quot;">​</a></h1><p>浏览器和 CDN 到底怎么缓存，全由服务器的一个响应头说了算——Cache-Control。这一章把 max-age、s-maxage、public/private、no-cache/no-store、以及 ETag 条件请求讲透，它们是后面一切缓存策略的字母表。</p><p>缓存分层的第一层是浏览器，第二层是 CDN。这两层怎么缓存你的页面，<strong>不是它们自己决定的，而是你的服务器用一个响应头告诉它们的</strong>——这个头叫 <strong><code>Cache-Control</code></strong>。理解它，是理解后面一切缓存策略的前提；它是缓存世界的<strong>字母表</strong>。</p><h2 id="两个问题模型" tabindex="-1">两个问题模型 <a class="header-anchor" href="#两个问题模型" aria-label="Permalink to &quot;两个问题模型&quot;">​</a></h2><p><code>Cache-Control</code> 看着指令一堆，但只要用两个问题去套，立刻就清晰了：</p><ol><li><strong>这份响应，能新鲜多久？</strong>（在多久之内可以直接拿缓存、不用问服务器）</li><li><strong>过了保鲜期，该怎么办？</strong>（直接扔掉重取？还是问一句「变了没」？还是先用着旧的？）</li></ol><p>几乎所有指令，都是在回答这两个问题之一。</p><h2 id="问题一-能新鲜多久" tabindex="-1">问题一：能新鲜多久 <a class="header-anchor" href="#问题一-能新鲜多久" aria-label="Permalink to &quot;问题一：能新鲜多久&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>含义</th></tr></thead><tbody><tr><td><code>max-age=60</code></td><td>这份响应 60 秒内算「新鲜」，期间直接用缓存，不问服务器</td></tr><tr><td><code>s-maxage=60</code></td><td><strong>同上，但只对「共享缓存」(CDN)生效</strong>，且优先级高于 <code>max-age</code></td></tr><tr><td><code>immutable</code></td><td>永不变，保鲜期内<strong>连「变了没」都不必问</strong>（用于带哈希的静态资源）</td></tr></tbody></table><p><code>max-age</code> 是「保鲜秒数」。关键区分在 <code>s-maxage</code>：</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong><code>max-age</code> 管浏览器，<code>s-maxage</code> 管 CDN。</strong> 「共享缓存(shared cache)」指 CDN 这种<strong>多人共用</strong>的缓存；「私有缓存(private cache)」指用户自己浏览器里那份。你常常想让<strong>浏览器只缓存很短、而 CDN 缓存很久</strong>——比如 <code>Cache-Control: s-maxage=3600, max-age=0</code>：浏览器每次都来问，但 CDN 替你把源站保护得死死的（一小时内源站最多渲染一次）。这个组合在 SSR 里极其常用。</p></div><h2 id="问题二-过期了怎么办" tabindex="-1">问题二：过期了怎么办 <a class="header-anchor" href="#问题二-过期了怎么办" aria-label="Permalink to &quot;问题二：过期了怎么办&quot;">​</a></h2><p>保鲜期一过，缓存里的东西就「陈旧(stale)」了。怎么处理，由这几个指令决定：</p><table tabindex="0"><thead><tr><th>指令</th><th>过期后的行为</th></tr></thead><tbody><tr><td>（默认）</td><td>陈旧后，通常会<strong>带验证器去问一句</strong>「变了没」（见下文 ETag）</td></tr><tr><td><code>no-cache</code></td><td><strong>每次使用前都要问</strong>服务器「变了没」——不是不缓存，是「缓存了也要先验证」</td></tr><tr><td><code>must-revalidate</code></td><td>一旦陈旧，<strong>必须</strong>成功验证才能用，不许「先用着旧的」</td></tr><tr><td><code>stale-while-revalidate=N</code></td><td><strong>先把旧的给用户（快），同时后台悄悄更新</strong>——下一章的主角</td></tr><tr><td><code>stale-if-error</code></td><td>源站挂了时，<strong>拿旧的顶上</strong>，别给用户报错</td></tr></tbody></table><h2 id="谁能缓存-public-与-private" tabindex="-1">谁能缓存：public 与 private <a class="header-anchor" href="#谁能缓存-public-与-private" aria-label="Permalink to &quot;谁能缓存：public 与 private&quot;">​</a></h2><p>还有一对指令决定「<strong>谁</strong>有资格缓存这份响应」——这在 SSR 里性命攸关：</p><table tabindex="0"><thead><tr><th>指令</th><th>含义</th></tr></thead><tbody><tr><td><code>public</code></td><td>任何缓存都可以存（包括 CDN 这种共享缓存）</td></tr><tr><td><code>private</code></td><td><strong>只有用户自己的浏览器</strong>能存，<strong>CDN 不许存</strong></td></tr><tr><td><code>no-store</code></td><td><strong>谁都不许存</strong>，每次都必须回源</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong><code>private</code> 和 <code>public</code> 用错，是 SSR 最危险的缓存 bug 来源。</strong> 一个带用户个人信息的页面（比如「你好，张三」），如果错标成 <code>public</code>，CDN 就会把「张三的页面」缓存下来，然后<strong>发给下一个访问的李四</strong>——李四看到了张三的名字。这是严重的信息泄露。<strong>含个性化 / 隐私内容的响应，必须 <code>private</code>（只存浏览器）或 <code>no-store</code>（干脆不存）。</strong> 「个性化内容怎么在 CDN 层安全地缓存」是个大难题，<a href="/Front2Full/manual/computer-programming/ssr/personalization">后面专门一章</a>攻它。</p></div><p><code>no-store</code> 和 <code>no-cache</code> 是另一对经典混淆：</p><ul><li><strong><code>no-store</code></strong> = <strong>绝不缓存</strong>，连存都不存（用于极敏感数据，如支付页）。</li><li><strong><code>no-cache</code></strong> = <strong>可以缓存，但每次用之前都要向服务器确认「变了没」</strong>。名字有误导性——它不是「不缓存」。</li></ul><h2 id="验证器-etag-与-304" tabindex="-1">验证器：ETag 与 304 <a class="header-anchor" href="#验证器-etag-与-304" aria-label="Permalink to &quot;验证器：ETag 与 304&quot;">​</a></h2><p>上面反复出现「问一句变了没」，这背后是 HTTP 的<strong>条件请求</strong>机制，靠<strong>验证器(validator)</strong> 实现，能在「内容没变」时省下重传整个 body 的开销：</p><ul><li>服务器首次响应时附上一个<strong>指纹</strong>：<code>ETag: &quot;abc123&quot;</code>（内容哈希）或 <code>Last-Modified: &lt;时间&gt;</code>。</li><li>缓存过期后要验证时，浏览器/CDN 带着这个指纹回来问：<code>If-None-Match: &quot;abc123&quot;</code>。</li><li>服务器一比：<strong>没变</strong> → 回一个 <code>304 Not Modified</code>（<strong>空 body</strong>，极小），缓存续命；<strong>变了</strong> → 回 <code>200</code> + 新内容。</li></ul><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>首次:  GET /article/42          → 200 + body + ETag: &quot;abc123&quot;</span></span>
<span class="line"><span>再次:  GET /article/42</span></span>
<span class="line"><span>       If-None-Match: &quot;abc123&quot;   → 304 Not Modified(没 body,几十字节)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>条件请求的价值：即便缓存过期了，<strong>验证一次也远比重新下载 / 重新渲染便宜</strong>——没变就是一个几十字节的 <code>304</code>。所以「过期」不等于「白缓存了」；带上 ETag，过期缓存还能靠 <code>304</code> 高效续命。SSR 框架通常会自动为你算 ETag。</p></div><h2 id="vary-缓存键还看哪些请求头" tabindex="-1">Vary：缓存键还看哪些请求头 <a class="header-anchor" href="#vary-缓存键还看哪些请求头" aria-label="Permalink to &quot;Vary：缓存键还看哪些请求头&quot;">​</a></h2><p>默认情况下，缓存用 <strong>URL</strong> 当键(key)。但有时<strong>同一个 URL，响应会因某个请求头不同而不同</strong>——比如按 <code>Accept-Encoding</code> 返回 gzip 或 br 压缩版。<code>Vary</code> 头就是告诉缓存：「<strong>这个 URL 的缓存，还要按这些请求头分开存</strong>」。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vary: Accept-Encoding        # 不同压缩方式各存一份,合理</span></span>
<span class="line"><span>Vary: Cookie                 # ⚠️ 危险!见下</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong><code>Vary: Cookie</code> 几乎等于关掉 CDN 缓存。</strong> 因为每个用户的 Cookie 都不同，<code>Vary: Cookie</code> 会让 CDN 为<strong>每个用户</strong>都存一份独立缓存——缓存键炸裂，命中率趋近于零。这又是「个性化 vs 缓存」矛盾的一个化身。记住：<strong><code>Vary</code> 的维度越多，缓存被切得越碎，命中率越低。</strong> 能不 <code>Vary</code> 就不 <code>Vary</code>。</p></div><h2 id="几个即取即用的配方" tabindex="-1">几个即取即用的配方 <a class="header-anchor" href="#几个即取即用的配方" aria-label="Permalink to &quot;几个即取即用的配方&quot;">​</a></h2><p>把上面拼起来，不同内容的典型 <code>Cache-Control</code>：</p><table tabindex="0"><thead><tr><th>内容类型</th><th>Cache-Control</th><th>意思</th></tr></thead><tbody><tr><td>带哈希的静态资源(<code>app.abc123.js</code>)</td><td><code>public, max-age=31536000, immutable</code></td><td>缓存一年、永不重验（文件名变了就是新文件）</td></tr><tr><td>可共享的 SSR 页（文章、商品）</td><td><code>public, s-maxage=60, stale-while-revalidate=300</code></td><td>CDN 缓存 60 秒，之后 5 分钟内先旧后新</td></tr><tr><td>个性化页（个人中心）</td><td><code>private, no-cache</code></td><td>只存浏览器，每次用前验证</td></tr><tr><td>敏感页（支付、密钥）</td><td><code>no-store</code></td><td>谁都别缓存</td></tr></tbody></table><h2 id="小结与下一章" tabindex="-1">小结与下一章 <a class="header-anchor" href="#小结与下一章" aria-label="Permalink to &quot;小结与下一章&quot;">​</a></h2><p><code>Cache-Control</code> 是缓存的字母表，用「能新鲜多久 / 过期怎么办 / 谁能缓存」三组指令，就能精确指挥浏览器和 CDN。<code>max-age</code> vs <code>s-maxage</code>、<code>public</code> vs <code>private</code>、<code>no-cache</code> vs <code>no-store</code>、以及 ETag 条件请求和 <code>Vary</code>——这些是后面每一章都会用到的词汇。</p><p>字母表有了，该看这些指令在<strong>最关键的那一层</strong>——CDN / 边缘——上是怎么发挥威力、又怎么把源站保护起来的。下一章深入 CDN 缓存。👉 <a href="/Front2Full/manual/computer-programming/ssr/cdn-caching">CDN / 边缘缓存：SSR 的 HTML 怎么被缓存</a>。</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] MDN.「Cache-Control.」<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Cache-Control" target="_blank" rel="noreferrer">https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Cache-Control</a> —— 全部指令的权威定义。</li><li>[2] MDN.「HTTP conditional requests / ETag.」<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Conditional_requests" target="_blank" rel="noreferrer">https://developer.mozilla.org/en-US/docs/Web/HTTP/Conditional_requests</a> —— 验证器与 304。</li><li>[3] Google.「HTTP caching — web.dev.」<a href="https://web.dev/articles/http-cache" target="_blank" rel="noreferrer">https://web.dev/articles/http-cache</a> —— 实战配方与 <code>Vary</code> 陷阱。</li></ul>`,37)])])}const b=e(d,[["render",c]]);export{h as __pageData,b as default};
